/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] =
    &[error_codes::ELECTION_UNKNOWN, error_codes::OUT_OF_RANGE];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `voting/board/read:electionUnknown`
    ///
    /// No election with this identifier exists for this community, or the caller may not see it.
    ///
    /// Declared `retryable: false`.
    pub const ELECTION_UNKNOWN: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "voting/board/read:electionUnknown",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `voting/board/read:outOfRange`
    ///
    /// `treeSize` is greater than the board's current size, or `from` is greater than the tree size read against.
    ///
    /// Declared `retryable: false`.
    pub const OUT_OF_RANGE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "voting/board/read:outOfRange",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
}
